WITH remaining_keys AS (SELECT id, session_id FROM web_events EXCEPT ALL SELECT id, session_id FROM web_events WHERE page <> '/search'), verified AS (SELECT s.* FROM web_events s JOIN remaining_keys k ON s.id = k.id AND s.session_id = k.session_id) SELECT s.id, s.session_id, s.event_type, s.page, s.event_time, s.duration_sec, (SELECT SUM(w2.duration_sec) FROM web_events w2 WHERE w2.session_id = s.session_id) AS sum_web_event_duration_sec FROM verified s ORDER BY event_type DESC NULLS FIRST;
